approved_command_preview:
$ErrorActionPreference = 'Stop'

$repo = [Environment]::GetEnvironmentVariable('DCOIR_REPO_ROOT','Machine')
$downloads = [Environment]::GetEnvironmentVariable('DCOIR_DOWNLOADS_DIR','Machine')
if ([string]::IsNullOrWhiteSpace($repo)) { throw 'DCOIR_REPO_ROOT is unavailable' }
if ([string]::IsNullOrWhiteSpace($downloads)) { throw 'DCOIR_DOWNLOADS_DIR is unavailable' }

Set-Location $repo

$expectedHead = '421fb8dbd5b03d068d3abb20b5865e1ccc82b67b'
$base = '9dc055d81fba2bcd4e840ad1e9c9645bdc6a6a20'
$branch = 'refactor/issue-550-dcoir-runtime-consolidation'

& git fetch --no-tags origin "+refs/heads/$branch`:refs/remotes/origin/$branch"
if ($LASTEXITCODE -ne 0) { throw 'Failed to fetch the PR branch' }

$actualHead = (& git rev-parse "refs/remotes/origin/$branch").Trim()
if ($LASTEXITCODE -ne 0 -or $actualHead -ne $expectedHead) {
    throw "PR head drift: expected $expectedHead but observed $actualHead"
}

& git checkout --detach $expectedHead
if ($LASTEXITCODE -ne 0) { throw 'Failed to checkout the exact PR head' }

& git merge-base --is-ancestor $base $expectedHead
if ($LASTEXITCODE -ne 0) { throw 'Expected PR base is not an ancestor of the exact PR head' }

$secretNames = @(
    'DCOIR_GITHUB_FG_TOKEN',
    'DCOIR_GITHUB_CL_TOKEN',
    'DCOIR_GEMINI_API',
    'DCOIR_OPENAI_API_KEY',
    'DCOIR_OPENAI_PROJECT_ID',
    'OPENAI_API_KEY'
)
foreach ($name in $secretNames) {
    [Environment]::SetEnvironmentVariable($name, $null, 'Machine')
    [Environment]::SetEnvironmentVariable($name, $null, 'Process')
    Remove-Item "Env:$name" -ErrorAction SilentlyContinue
}

$expectedFiles = @(
    '.github/dcoir_review/ARCHITECTURE.md',
    '.github/dcoir_review/scripts/dcoir_review_architecture_inventory.py',
    '.github/dcoir_review/scripts/dcoir_review_runtime_module_loader_selftest.py',
    '.github/dcoir_review/scripts/dcoir_review_runtime_provenance.py'
)
$changedFiles = @(& git diff --name-only "$base...$expectedHead")
$scopeDelta = @(
    Compare-Object `
        -ReferenceObject ($expectedFiles | Sort-Object) `
        -DifferenceObject ($changedFiles | Sort-Object)
)
if ($scopeDelta.Count -ne 0) {
    throw "Unexpected PR file scope: $($changedFiles -join ', ')"
}

& python -m py_compile `
    '.github/dcoir_review/scripts/dcoir_review_architecture_inventory.py' `
    '.github/dcoir_review/scripts/dcoir_review_runtime_module_loader_selftest.py' `
    '.github/dcoir_review/scripts/dcoir_review_runtime_provenance.py'
if ($LASTEXITCODE -ne 0) { throw 'Python compilation failed' }

& python '.github/dcoir_review/scripts/dcoir_review_runtime_module_loader_selftest.py'
if ($LASTEXITCODE -ne 0) { throw 'DCOIR runtime module-loader selftest failed' }

$inventoryPath = Join-Path $downloads 'dcoir-review-architecture-inventory.json'
& python '.github/dcoir_review/scripts/dcoir_review_architecture_inventory.py' |
    Out-File -FilePath $inventoryPath -Encoding utf8
if ($LASTEXITCODE -ne 0) { throw 'DCOIR architecture inventory failed' }

$inventory = Get-Content $inventoryPath -Raw | ConvertFrom-Json
if (@($inventory.missing_modules).Count -ne 0) {
    throw "Architecture inventory has missing modules: $($inventory.missing_modules -join ', ')"
}
if ([int]$inventory.max_numbered_version -ne 58) {
    throw "Numbered production patch ceiling changed: $($inventory.max_numbered_version)"
}

$provenancePath = Join-Path $downloads 'dcoir-review-runtime-provenance.json'
& python '.github/dcoir_review/scripts/dcoir_review_runtime_provenance.py' |
    Out-File -FilePath $provenancePath -Encoding utf8
if ($LASTEXITCODE -ne 0) { throw 'DCOIR runtime provenance characterization failed' }

$provenance = Get-Content $provenancePath -Raw | ConvertFrom-Json
if (@($provenance.production_patch_sequence).Count -lt 1) {
    throw 'Runtime provenance did not observe the current production patch sequence'
}

& git diff --check "$base...$expectedHead"
if ($LASTEXITCODE -ne 0) { throw 'git diff --check failed' }

$worktreeState = @(& git status --porcelain)
if ($worktreeState.Count -ne 0) {
    throw "Characterization modified the worktree: $($worktreeState -join '; ')"
}

Write-Host "PR #553 exact-head architecture characterization passed: $expectedHead"
Write-Host "Inventory artifact: $inventoryPath"
Write-Host "Runtime provenance artifact: $provenancePath"

